import data from './campusPlan.json';
import type { SpaceType } from '../domain/model';

/**
 * The UCC Pasto campus as drawn on PLANOS_UCC_2025_-_B.dwg: per floor, the walls (an SVG path in metres,
 * y down) and the rooms recognised on it with their outline, oriented rectangle and the estimated
 * capacity, seats and computers. Generated by tools/plan in the backend repository.
 */
export interface PlanRoom {
  spaceId: string;
  name: string;
  type: SpaceType;
  block: 'A' | 'B';
  floor: number;
  areaSqm: number;
  capacity: number;
  seatRows: number | null;
  seatColumns: number | null;
  computers: number;
  polygon: [number, number][];
  rect: { cx: number; cy: number; w: number; h: number; angle: number };
}

export interface PlanFloor {
  floor: number;
  name: string;
  width: number;
  height: number;
  walls: string;
  rooms: PlanRoom[];
}

export const PLAN_SOURCE: string = data.source;
export function validatePlanFloors(value: unknown): PlanFloor[] {
  if (!Array.isArray(value) || value.length === 0) throw new RangeError('campus plan must contain at least one floor');
  const floorIds = new Set<number>();
  const roomIds = new Set<string>();
  for (const rawFloor of value) {
    if (!rawFloor || typeof rawFloor !== 'object') throw new RangeError('campus floor must be an object');
    const floor = rawFloor as PlanFloor;
    if (!Number.isSafeInteger(floor.floor) || floor.floor < 0 || floorIds.has(floor.floor)) {
      throw new RangeError('campus floor numbers must be unique non-negative integers');
    }
    if (typeof floor.name !== 'string' || !floor.name.trim() || typeof floor.walls !== 'string'
        || !Number.isFinite(floor.width) || floor.width <= 0 || !Number.isFinite(floor.height) || floor.height <= 0
        || !Array.isArray(floor.rooms)) throw new RangeError('campus floor metadata is invalid');
    floorIds.add(floor.floor);
    for (const rawRoom of floor.rooms) {
      if (!rawRoom || typeof rawRoom !== 'object') throw new RangeError('campus room must be an object');
      const room = rawRoom as PlanRoom;
      if (typeof room.spaceId !== 'string' || !room.spaceId.trim() || roomIds.has(room.spaceId)
          || room.floor !== floor.floor || !Number.isFinite(room.areaSqm) || room.areaSqm <= 0
          || !Number.isSafeInteger(room.capacity) || room.capacity < 1
          || !Array.isArray(room.polygon) || room.polygon.length < 3
          || room.polygon.some((point) => !Array.isArray(point) || point.length !== 2
            || !point.every(Number.isFinite))) throw new RangeError('campus room geometry or identity is invalid');
      const { cx, cy, w, h, angle } = room.rect;
      if (![cx, cy, w, h, angle].every(Number.isFinite) || w <= 0 || h <= 0) {
        throw new RangeError('campus room rectangle is invalid');
      }
      const { seatRows, seatColumns } = room;
      if (!((seatRows === null && seatColumns === null)
          || (Number.isSafeInteger(seatRows) && Number.isSafeInteger(seatColumns)
            && seatRows! > 0 && seatColumns! > 0 && seatRows! * seatColumns! <= 1_000))) {
        throw new RangeError('campus room seat layout is invalid');
      }
      if (!Number.isSafeInteger(room.computers) || room.computers < 0) {
        throw new RangeError('campus room equipment count is invalid');
      }
      roomIds.add(room.spaceId);
    }
  }
  return value as PlanFloor[];
}

export const PLAN_FLOORS: PlanFloor[] = validatePlanFloors(data.floors);
export const PLAN_ROOMS: PlanRoom[] = PLAN_FLOORS.flatMap((floor) => floor.rooms);
const BY_ID = new Map(PLAN_ROOMS.map((room) => [room.spaceId, room]));
export const planRoom = (spaceId: string): PlanRoom | undefined => BY_ID.get(spaceId);
export const floorName = (floor: number): string => PLAN_FLOORS.find((f) => f.floor === floor)?.name ?? `Piso ${floor}`;
